package view;

import bus.schedule.ScheduleBUS;
import bus.schedule.ScheduleException;
import java.awt.*;
import java.time.LocalDate;
import java.util.List;
import java.util.concurrent.ExecutionException;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import model.auth.AuthenticatedSession;
import model.schedule.ScheduleModels.*;
import view.component.UIStyle;

public final class SchedulePanel extends JPanel {
    private final AuthenticatedSession session;private final ScheduleBUS bus;private final JTextField search=new JTextField();private final JTextField from=new JTextField();private final JTextField to=new JTextField();private final JLabel status=new JLabel(" ");private final JLabel paging=new JLabel(" ");private final DefaultTableModel model=model("Mã","Bác sĩ","Chuyên khoa","Ca","Ngày làm","Thời gian","Địa điểm","Trạng thái","Khung giờ","Đã đặt");private final JTable table=new JTable(model);private Page<Assignment> page;private int currentPage;
    public SchedulePanel(AuthenticatedSession s,ScheduleBUS b){session=s;bus=b;setLayout(new BorderLayout(0,12));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(18,20,20,20));add(header(),BorderLayout.NORTH);JPanel body=new JPanel(new BorderLayout(0,10));body.setOpaque(false);body.add(toolbar(),BorderLayout.NORTH);UIStyle.table(table);table.setAutoCreateRowSorter(true);table.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(e.getClickCount()==2&&table.getSelectedRow()>=0)showSelectedDetail();}});body.add(new JScrollPane(table),BorderLayout.CENTER);body.add(footer(),BorderLayout.SOUTH);add(body,BorderLayout.CENTER);load();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JLabel title=new JLabel("Quản trị lịch làm việc");title.setFont(new Font("Segoe UI",Font.BOLD,25));title.setForeground(MainFrame.TEXT);p.add(title,BorderLayout.WEST);status.setForeground(MainFrame.MUTED);p.add(status,BorderLayout.CENTER);JButton r=new JButton("Làm mới");r.addActionListener(e->load());p.add(r,BorderLayout.EAST);return p;}
    private JPanel toolbar(){JPanel p=new JPanel(new BorderLayout(8,6));p.setOpaque(false);search.setPreferredSize(new Dimension(250,34));search.addActionListener(e->{currentPage=0;load();});p.add(search,BorderLayout.WEST);JPanel dates=new JPanel(new GridLayout(1,4,6,0));dates.setOpaque(false);dates.add(new JLabel("Từ ngày"));dates.add(from);dates.add(new JLabel("Đến ngày"));dates.add(to);from.setToolTipText("yyyy-MM-dd");to.setToolTipText("yyyy-MM-dd");p.add(dates,BorderLayout.CENTER);JButton find=new JButton("Lọc");find.addActionListener(e->{currentPage=0;load();});p.add(find,BorderLayout.EAST);JButton add=new JButton("Phân công bác sĩ");add.setBackground(MainFrame.BLUE);add.setForeground(Color.WHITE);add.setOpaque(true);add.setBorderPainted(false);add.addActionListener(e->assign());p.add(add,BorderLayout.SOUTH);return p;}
    private JPanel footer(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JButton prev=new JButton("‹ Trước"),next=new JButton("Sau ›");prev.addActionListener(e->{if(currentPage>0){currentPage--;load();}});next.addActionListener(e->{if(page!=null&&currentPage+1<page.totalPages()){currentPage++;load();}});JPanel nav=new JPanel(new FlowLayout(FlowLayout.RIGHT,6,0));nav.setOpaque(false);nav.add(prev);nav.add(paging);nav.add(next);p.add(nav,BorderLayout.EAST);return p;}
    private void load(){worker(()->bus.search(session,search.getText(),date(from),date(to),currentPage,20),p->{page=p;model.setRowCount(0);for(Assignment a:p.rows())model.addRow(new Object[]{a.id(),a.doctorName(),a.specialty(),a.shiftName(),a.workDate(),a.start()+" - "+a.end(),safe(a.location()),a.status(),a.slotCount(),a.bookedCount()});paging.setText("Trang "+(currentPage+1)+" / "+p.totalPages()+" · "+p.totalCount()+" phân công");status.setText("Phân công đã xác nhận sẽ tự tạo khung giờ đặt lịch cho bác sĩ.");});}
    private void assign(){JComboBox<Doctor> doctors=new JComboBox<>();JComboBox<Shift> shifts=new JComboBox<>();JTextField day=new JTextField(LocalDate.now().plusDays(1).toString()),location=new JTextField("Phòng khám Thu Cúc"),note=new JTextField();try{for(Doctor d:bus.doctors(session))doctors.addItem(d);for(Shift s:bus.shifts(session))shifts.addItem(s);}catch(ScheduleException e){error(e);return;}doctors.setRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> l,Object v,int i,boolean s,boolean f){super.getListCellRendererComponent(l,v,i,s,f);if(v instanceof Doctor d)setText(d.name()+" · "+d.specialty());return this;}});shifts.setRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> l,Object v,int i,boolean s,boolean f){super.getListCellRendererComponent(l,v,i,s,f);if(v instanceof Shift x)setText(x.name()+" ("+x.start()+" - "+x.end()+")");return this;}});JPanel form=new JPanel(new GridLayout(0,2,7,7));form.add(new JLabel("Bác sĩ *"));form.add(doctors);form.add(new JLabel("Ca làm việc *"));form.add(shifts);form.add(new JLabel("Ngày làm * yyyy-MM-dd"));form.add(day);form.add(new JLabel("Địa điểm"));form.add(location);form.add(new JLabel("Ghi chú"));form.add(note);if(JOptionPane.showConfirmDialog(this,form,"Phân công bác sĩ",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{Doctor d=(Doctor)doctors.getSelectedItem();Shift sh=(Shift)shifts.getSelectedItem();bus.assign(session,new Draft(d.id(),sh.id(),LocalDate.parse(day.getText().trim()),location.getText().trim(),note.getText().trim()));JOptionPane.showMessageDialog(this,"Đã phân công và tạo khung giờ đặt lịch.");load();}catch(Exception e){error(e);}}
    private void showSelectedDetail(){int r=table.getSelectedRow();if(r<0||page==null)return;int m=table.convertRowIndexToModel(r);if(m<0||m>=page.rows().size())return;Assignment a=page.rows().get(m);new ScheduleDetailDialog(SwingUtilities.getWindowAncestor(this),a,()->cancelAssignment(a)).setVisible(true);}
    private void cancelAssignment(Assignment a){if(JOptionPane.showConfirmDialog(this,"Hủy phân công ngày "+a.workDate()+" của "+a.doctorName()+"?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{bus.cancel(session,a.id());JOptionPane.showMessageDialog(this,"Đã hủy phân công.");load();}catch(ScheduleException e){error(e);}}
    private LocalDate date(JTextField f)throws ScheduleException{if(f.getText().isBlank())return null;try{return LocalDate.parse(f.getText().trim());}catch(Exception e){throw new ScheduleException("Ngày lọc phải có dạng yyyy-MM-dd.");}}
    private <T>void worker(java.util.concurrent.Callable<T> c,java.util.function.Consumer<T> done){new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return c.call();}protected void done(){try{done.accept(get());}catch(InterruptedException e){Thread.currentThread().interrupt();error(e);}catch(ExecutionException e){error(e.getCause());}}}.execute();}
    private void error(Throwable e){JOptionPane.showMessageDialog(this,e.getMessage()==null?"Có lỗi xảy ra.":e.getMessage(),"Lịch làm việc",JOptionPane.ERROR_MESSAGE);}
    private static DefaultTableModel model(String... c){return new DefaultTableModel(c,0){public boolean isCellEditable(int r,int c){return false;}};}
    private static String safe(String s){return s==null||s.isBlank()?"—":s;}
}
